fn pools()->Value{kmoCellDataPool.clear();kmoFormulaDataPool.clear();let mut cs=vec![];let mut fs=vec![];for _ in 0..22{let c=kmoCellDataPool.borrowObject();{let mut d=c.borrow_mut();d.ixf=17;d.formulaType=3;d.id=51;d.hasComment=true;d.isPicInCell=true;}let f=kmoFormulaDataPool.borrowObject();{let mut d=f.borrow_mut();d.setTokens(17,31);d.setCacheValueId(51);d.setCalcFlags(-1);}cs.push(c);fs.push(f);}let mut cleared=vec![];for i in 0..22{kmoCellDataPool.returnObject(Some(cs[i].clone()));kmoFormulaDataPool.returnObject(Some(fs[i].clone()));cleared.push(json!([cell(&cs[i]),fml(&fs[i])]));}let mut ids=vec![];for _ in 0..22{let c=kmoCellDataPool.borrowObject();let f=kmoFormulaDataPool.borrowObject();let ci=cs.iter().position(|v|Rc::ptr_eq(v,&c)).map_or(-1,|i|i as i32);let fi=fs.iter().position(|v|Rc::ptr_eq(v,&f)).map_or(-1,|i|i as i32);ids.push(json!([ci,fi,cell(&c),fml(&f)]));}kmoCellDataPool.clear();kmoFormulaDataPool.clear();json!({"cleared":cleared,"ids":ids,"nullReturn":kmoCellDataPool.returnObject(None).is_none()&&kmoFormulaDataPool.returnObject(None).is_none()})}
